# -*- coding: utf-8 -*-
# 第 10 批（A2）：空氣污染防制法（107/8/1）第51條～第100條
AP = "ENV-01"
Q = [
(AP,"第51條",3,"空污法-罰則",
 "違反突發事故緊急應變義務或不遵行主管機關命令，因而致人於死者，其刑責為何？",
 ["處無期徒刑或七年以上有期徒刑，得併科新臺幣三千萬元以下罰金","處十年以上有期徒刑，得併科新臺幣一千萬元以下之罰金","處五年以上十二年以下有期徒刑，得併科二千萬元以下罰金","處三年以上十年以下有期徒刑，得併科五百萬元以下之罰金"],"a",
 "第51條：違反第33條第1項未立即採取緊急應變措施或不遵行主管機關依第33條第2項所為之命令，因而致人於死者，處無期徒刑或七年以上有期徒刑，得併科新臺幣三千萬元以下罰金；致重傷者處三年以上十年以下有期徒刑，得併科二千五百萬元以下罰金；致危害人體健康導致疾病者處六月以上五年以下有期徒刑，得併科二千萬元以下罰金。第57條並定明法人兩罰規定。",
 "What criminal penalty applies when failure to respond to a sudden incident causes death?",
 ["Life imprisonment or at least seven years, with a fine of up to NT$30 million","At least ten years imprisonment, with a fine of up to NT$10 million added","Five to twelve years imprisonment, with a fine of up to NT$20 million added","Three to ten years imprisonment, with a fine of up to NT$5 million added"],
 "Article 51."),

(AP,"第52條",3,"空污法-罰則",
 "違反國際環保公約管制物質辦法中有關輸入或輸出限制之規定者，如何處罰？",
 ["處六月以上五年以下有期徒刑，得併科新臺幣三十萬元以上一百五十萬元以下罰金","處一年以上七年以下有期徒刑，得併科新臺幣一百萬元以上五百萬元以下罰金","處拘役或新臺幣十萬元以上五十萬元以下罰金，並得沒入其輸出入之物質","處三年以下有期徒刑，得併科新臺幣二十萬元以上三百萬元以下之罰金"],"a",
 "第52條：違反第31條第2項所定辦法中有關輸入或輸出限制規定者，處六月以上五年以下有期徒刑，得併科新臺幣三十萬元以上一百五十萬元以下罰金。若僅違反該辦法有關製造、販賣或使用之許可、記錄、申報及管理事項規定者，則依第68條處十萬元以上二百萬元以下罰鍰。",
 "How are import or export restrictions on treaty-controlled substances punished?",
 ["Six months to five years imprisonment, with a fine of NT$300,000 to NT$1.5 million","One to seven years imprisonment, with a fine of NT$1 million to NT$5 million added","Detention or a fine of NT$100,000 to NT$500,000, with the substances confiscated","Up to three years imprisonment, with a fine of NT$200,000 to NT$3 million added"],
 "Article 52; compare the administrative fine in Article 68."),

(AP,"第53條",3,"空污法-罰則",
 "排放管道排放之有害空氣污染物違反排放限值，足以生損害於他人生命、身體健康者，如何處罰？",
 ["處七年以下有期徒刑，得併科新臺幣一百萬元以上一千五百萬元以下罰金","處五年以下有期徒刑，得併科新臺幣五十萬元以上五百萬元以下之罰金","處十年以下有期徒刑，得併科新臺幣三百萬元以上三千萬元以下罰金","處三年以下有期徒刑，得併科新臺幣二十萬元以上二百萬元以下罰金"],"a",
 "第53條：公私場所固定污染源排放管道排放空氣污染物違反第20條第2項所定標準之有害空氣污染物排放限值，足以生損害於他人之生命、身體健康者，處七年以下有期徒刑，得併科新臺幣一百萬元以上一千五百萬元以下罰金。施行細則第14條區分排放標準值與排放限值：違反標準值依第62條第1項第1款裁罰，違反限值則依第53條移送司法機關。",
 "What penalty applies to exceeding hazardous pollutant emission limits at a stack, endangering life or health?",
 ["Up to seven years imprisonment, with a fine of NT$1 million to NT$15 million","Up to five years imprisonment, with a fine of NT$500,000 to NT$5 million added","Up to ten years imprisonment, with a fine of NT$3 million to NT$30 million added","Up to three years imprisonment, with a fine of NT$200,000 to NT$2 million added"],
 "Article 53; see Enforcement Rules Article 14."),

(AP,"第54條",3,"空污法-罰則",
 "依本法有申請或申報義務者，明知不實而申請、申報不實或於業務上文書虛偽記載，如何處罰？",
 ["處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金","處一年以下有期徒刑、拘役或科或併科新臺幣十萬元以上一百萬元以下罰金","處五年以下有期徒刑、拘役或科或併科新臺幣五十萬元以上一千萬元以下罰金","處新臺幣二十萬元以上二百萬元以下罰鍰，並得按次處罰至改善完成為止"],"a",
 "第54條：依本法規定有申請或申報義務，明知為不實之事項而申請、申報不實或於業務上作成之文書為虛偽記載者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金。第57條規定法人之代表人、受僱人等因執行業務犯第51條至第54條之罪者，對法人或自然人並科各該條十倍以下之罰金。",
 "How is knowingly false application or reporting punished?",
 ["Up to three years imprisonment or detention, and/or a fine of NT$200,000 to NT$5 million","Up to one year imprisonment or detention, and/or a fine of NT$100,000 to NT$1 million","Up to five years imprisonment or detention, and/or a fine of NT$500,000 to NT$10 million","An administrative fine of NT$200,000 to NT$2 million, imposed repeatedly until corrected"],
 "Article 54; see also Article 57."),

(AP,"第55條",3,"空污法-罰則",
 "無空氣污染防制設備或設備未運作而燃燒易生特殊有害健康之物質者，如何處罰？該物質由何機關公告？",
 ["處三年以下有期徒刑、拘役或科或併科二十萬元以上五百萬元以下罰金；物質由中央主管機關公告","處一年以下有期徒刑、拘役或科或併科十萬元以上一百萬元以下罰金；物質由地方主管機關公告","處新臺幣十萬元以上五百萬元以下罰鍰並令停工；該物質由目的事業主管機關按產業別公告","處七年以下有期徒刑，得併科一百萬元以上一千五百萬元以下罰金；物質由行政院核定公告"],"a",
 "第55條：無空氣污染防制設備或空氣污染防制設備未運作而燃燒易生特殊有害健康之物質者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金；前項易生特殊有害健康之物質，由中央主管機關公告之。第57條並定法人兩罰。",
 "How is burning specially harmful substances without operating control equipment punished, and who lists them?",
 ["Up to three years imprisonment or detention and/or NT$200,000 to NT$5 million; listed by the central authority","Up to one year imprisonment or detention and/or NT$100,000 to NT$1 million; listed by the local authority","An administrative fine of NT$100,000 to NT$5 million plus shutdown; listed by industry authorities by sector","Up to seven years imprisonment with NT$1 million to NT$15 million; listed by the Executive Yuan"],
 "Article 55."),

(AP,"第56條",3,"空污法-罰則",
 "不遵行主管機關所為停工、停業或停止操作命令者，其刑責有何不同？",
 ["不遵行停工或停業命令者處負責人三年以下有期徒刑、拘役或科或併科二十萬元以上五百萬元以下罰金；不遵行停止操作或停止作為命令者處一年以下有期徒刑、拘役或科或併科二十萬元以上一百萬元以下罰金","不遵行停工或停業命令者處負責人一年以下有期徒刑、拘役或科或併科十萬元以上一百萬元以下罰金；不遵行停止操作或停止作為命令者處三年以下有期徒刑、拘役或科或併科五十萬元以上五百萬元以下罰金","不遵行停工或停業命令者處新臺幣一百萬元以上一千萬元以下罰鍰並得按次處罰；不遵行停止操作或停止作為命令者處新臺幣五十萬元以上五百萬元以下罰鍰，均不科處自由刑","不遵行停工或停業命令者處負責人五年以下有期徒刑並得併科一千萬元以下罰金；不遵行停止操作或停止作為命令者僅得由主管機關廢止其操作許可證，不另處刑罰或罰鍰"],"a",
 "第56條：公私場所不遵行主管機關依本法所為停工或停業之命令者，處負責人三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金；不遵行依第33條第2項、第67條第2項所為停止操作或依第67條第2項所為停止作為之命令者，處一年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上一百萬元以下罰金。",
 "How do penalties differ for defying shutdown orders versus stop-operation orders?",
 ["Defying a shutdown or suspension order: the responsible person faces up to three years and/or NT$200,000 to NT$5 million; defying a stop-operation or stop-act order: up to one year and/or NT$200,000 to NT$1 million","Defying a shutdown or suspension order: the responsible person faces up to one year and/or NT$100,000 to NT$1 million; defying a stop-operation or stop-act order: up to three years and/or NT$500,000 to NT$5 million","Defying a shutdown or suspension order draws an administrative fine of NT$1 million to NT$10 million imposed repeatedly; defying a stop-operation or stop-act order draws NT$500,000 to NT$5 million, with no imprisonment in either case","Defying a shutdown or suspension order: the responsible person faces up to five years and a fine of up to NT$10 million; defying a stop-operation or stop-act order merely allows revocation of the operating permit with no fine or imprisonment"],
 "Article 56."),

(AP,"第57條",3,"空污法-兩罰",
 "法人之代表人、受僱人因執行業務犯本法之罪者，對該法人或自然人之處罰為何？",
 ["除處罰行為人外，對該法人或自然人亦科以各該條十倍以下之罰金","除處罰行為人外，對該法人或自然人亦科以各該條三倍以下之罰金","僅處罰實際行為人，對該法人或自然人不另科處任何罰金或罰鍰","除處罰行為人外，並應命該法人停工一年及廢止其全部操作許可證"],"a",
 "第57條：法人之代表人、法人或自然人之代理人、受僱人或其他從業人員因執行業務，犯第51條至第54條、第55條第1項或第56條之罪者，除依各該條規定處罰其行為人外，對該法人或自然人亦科以各該條十倍以下之罰金。",
 "What applies to a juristic person when its staff commit an offence in the course of business?",
 ["Besides punishing the actor, the juristic or natural person is fined up to ten times that article's fine","Besides punishing the actor, the juristic or natural person is fined up to three times that article's fine","Only the actual actor is punished; no fine of any kind is imposed on the juristic or natural person","Besides punishing the actor, the juristic person must shut down for a year and lose all operating permits"],
 "Article 57."),

(AP,"第58條",2,"空污法-罰則",
 "特殊性工業區開發者未設置緩衝地帶或空氣品質監測設施者，如何處罰？",
 ["處新臺幣五十萬元以上二千萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者按次處罰","處新臺幣十萬元以上一百萬元以下罰鍰，並通知限期改善，屆期未完成改善者移送司法機關","處新臺幣二萬元以上一百萬元以下罰鍰，並令其停工，不再通知限期改善或按次處罰","處新臺幣一百萬元以上五千萬元以下罰鍰，並廢止其工業區開發許可及勒令歇業"],"a",
 "第58條：特殊性工業區開發者違反第15條第1項未設置緩衝地帶或適當地區設置空氣品質監測設施，或違反第15條第2項所定標準有關緩衝地帶設置、監測設施設置規範、記錄、申報及管理事項之規定者，處新臺幣五十萬元以上二千萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰。",
 "How is a special industrial park developer punished for missing buffer zones or monitors?",
 ["A fine of NT$500,000 to NT$20 million, with notice to correct and repeated fines if not corrected in time","A fine of NT$100,000 to NT$1 million, with notice to correct and referral for prosecution if not corrected","A fine of NT$20,000 to NT$1 million plus a shutdown order, with no correction notice or repeated fines","A fine of NT$1 million to NT$50 million, plus revocation of the park development permit and closure"],
 "Article 58."),

(AP,"第59條",3,"空污法-罰則",
 "公私場所未採取突發事故緊急應變措施或未依規定通報者，其行政罰為何？",
 ["處新臺幣十萬元以上二千萬元以下罰鍰；情節重大者得令停工或停業，必要時並得廢止其操作許可或勒令歇業","處新臺幣二萬元以上一百萬元以下罰鍰；情節重大者得令停工，但不得廢止其操作許可或勒令其歇業","處新臺幣五千元以上十萬元以下罰鍰；情節重大者由中央主管機關移送司法機關偵辦並公布名稱","處新臺幣二十萬元以上二百萬元以下罰鍰；並通知限期補正，屆期未補正者始得令其停工或停業"],"a",
 "第59條：公私場所違反第33條第1項未採取緊急應變措施或未依規定通報、不遵行主管機關依第33條第2項所為採取必要措施之命令、或違反第33條第3項未切實執行緊急應變措施計畫者，處新臺幣十萬元以上二千萬元以下罰鍰；情節重大者，得令其停工或停業，必要時並得廢止其操作許可或勒令歇業。情節重大之認定依第96條第1項各款。",
 "What administrative fine applies for failing to respond to or report a sudden incident?",
 ["A fine of NT$100,000 to NT$20 million; in serious cases shutdown or suspension, and permit revocation or closure if needed","A fine of NT$20,000 to NT$1 million; in serious cases shutdown only, with no revocation of the operating permit or closure","A fine of NT$5,000 to NT$100,000; in serious cases the central authority refers the case for prosecution and names the firm","A fine of NT$200,000 to NT$2 million, with notice to correct, and shutdown only if correction is not made in time"],
 "Article 59; serious cases defined in Article 96."),

(AP,"第60條",2,"空污法-罰則",
 "公私場所違反一級防制區禁止新設或變更固定污染源規定者，如何處罰？",
 ["處新臺幣二萬元以上一百萬元以下罰鍰；違反者為工商廠、場者處十萬元以上二千萬元以下罰鍰，並令停工","處新臺幣一千二百元以上十萬元以下罰鍰；違反者為工商廠、場者處十萬元以上五百萬元以下罰鍰並停業","處新臺幣二十萬元以上二百萬元以下罰鍰；違反者為工商廠、場者處五十萬元以上一千萬元以下罰鍰","處新臺幣五十萬元以上二千萬元以下罰鍰；違反者為工商廠、場者一律廢止其操作許可並勒令歇業"],"a",
 "第60條：公私場所違反第6條第1項規定者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上二千萬元以下罰鍰，並令停工。第6條第1項規定一級防制區內除維繫住戶民生需要之設施、國家公園經營管理必要設施或國防設施外，不得新設或變更固定污染源。",
 "How is a breach of the Class 1 district construction ban punished?",
 ["A fine of NT$20,000 to NT$1 million; for industrial plants NT$100,000 to NT$20 million plus a shutdown order","A fine of NT$1,200 to NT$100,000; for industrial plants NT$100,000 to NT$5 million plus suspension of business","A fine of NT$200,000 to NT$2 million; for industrial plants a fine of NT$500,000 to NT$10 million is imposed","A fine of NT$500,000 to NT$20 million; industrial plants always lose the operating permit and are closed down"],
 "Article 60; see Article 6, paragraph 1."),

(AP,"第61條",2,"空污法-罰則",
 "未依規定削減污染物排放量或違反削減量差額認可、保留、抵換、交易管理規定者，如何處罰？",
 ["處二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰，並通知限期補正或改善，屆期未完成者按次處罰","處一千二百元以上十萬元以下罰鍰，工商廠、場處十萬元以上五百萬元以下罰鍰，並得逕行令其停工或勒令其歇業","處二十萬元以上二百萬元以下罰鍰，工商廠、場處五十萬元以上一千萬元以下罰鍰，且不得通知限期補正或改善","處十萬元以上二千萬元以下罰鍰，工商廠、場加倍處罰，並應於處分後立即廢止其設置及操作許可證"],"a",
 "第61條：公私場所未依第8條第3項規定削減污染物排放量，或違反第8條第5項所定辦法有關實際削減量差額認可、保留、抵換、交易及管理事項之規定者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處十萬元以上二千萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者按次處罰；情節重大者得令停工或停業，必要時並得廢止其操作許可或勒令歇業。",
 "How are failures to reduce emissions or to follow offset trading rules punished?",
 ["NT$20,000 to NT$1 million, or NT$100,000 to NT$20 million for industrial plants, with notice to correct and repeated fines if not corrected","NT$1,200 to NT$100,000, or NT$100,000 to NT$5 million for industrial plants, with immediate shutdown or an order to close the business down","NT$200,000 to NT$2 million, or NT$500,000 to NT$10 million for industrial plants, with no notice to correct or improve being given at all","NT$100,000 to NT$20 million, doubled for industrial plants, with the installation and operating permits revoked right after the penalty"],
 "Article 61."),

(AP,"第62條",3,"空污法-罰則",
 "公私場所違反排放標準、季排放量申報或監測設施規定者，其罰鍰額度及併罰規定為何？",
 ["處二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰；同一場所有數污染源或同一污染源排放數污染物者應分別處罰","處二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰；同一場所之數污染源應合併以一違規行為論處","處五千元以上十萬元以下罰鍰，工商廠、場處二十萬元以上一百萬元以下罰鍰；並一律移送司法機關偵辦處理","處十萬元以上二千萬元以下罰鍰，不分公私場所或工商廠、場；同一污染源排放數污染物者僅得處罰一次"],"a",
 "第62條第1項：公私場所違反第20條第1項排放標準、第21條第1項季排放量申報、第22條監測或檢驗測定、第23條收集與防制設施、第24條許可證內容、第25條重新申請、第27條第2項總量濃度或第33條第3項應變計畫補正等規定者，處新臺幣二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰，並通知限期補正或改善，屆期未完成者按次處罰。第2項：於同一公私場所有數固定污染源或同一固定污染源排放數空氣污染物者，應分別處罰。",
 "What fine and cumulative rule apply to breaches of emission, reporting and monitoring duties?",
 ["NT$20,000 to NT$1 million, or NT$100,000 to NT$20 million for industrial plants; several sources or several pollutants are punished separately","NT$20,000 to NT$1 million, or NT$100,000 to NT$20 million for industrial plants; several sources at one site count as a single violation","NT$5,000 to NT$100,000, or NT$200,000 to NT$1 million for industrial plants; and every such case is referred for criminal prosecution","NT$100,000 to NT$20 million for all premises alike; where one source emits several pollutants only one penalty may be imposed"],
 "Article 62, paragraphs 1 and 2."),

(AP,"第62條",2,"空污法-罰則情節重大",
 "依第六十二條第一項處罰之情形，主管機關於何種情況下得令停工或停業並廢止操作許可？",
 ["情節重大者，得令其停工或停業，必要時並得廢止其操作許可或勒令歇業","僅於第二次處罰後即應一律令其停工，並同時廢止其設置及操作許可證","僅於經司法機關判決有罪確定後，始得令其停工或廢止其操作許可證","僅於公私場所自報停工期間，主管機關始得廢止其操作許可或勒令歇業"],"a",
 "第62條第1項：違反該項各款情形者，並通知限期補正或改善，屆期仍未補正或完成改善者按次處罰；情節重大者，得令其停工或停業，必要時，並得廢止其操作許可或勒令歇業。第96條第1項列舉情節重大之七款情形，包括未經合法登記或許可之污染源違規、自報停工改善經查證非屬實、一年內經二次限期改善仍繼續違規等。",
 "When may the authority order shutdown and revoke the permit under Article 62(1)?",
 ["Where the case is serious, it may order shutdown or suspension and, if necessary, revoke the permit or close the business","After a second penalty it must always order shutdown and at the same time revoke both installation and operating permits","Only after a court has convicted the operator may shutdown be ordered or the operating permit be revoked at all","Only during a self-reported shutdown period may the authority revoke the operating permit or order closure"],
 "Article 62, paragraph 1; Article 96 lists serious cases."),

(AP,"第63條",2,"空污法-罰則",
 "公私場所未取得許可證即逕行設置、變更或操作固定污染源者，如何處罰？",
 ["處二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰，並令停工及限期申請取得許可證","處二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰，但不得令停工僅得限期改善","處一千二百元以上十萬元以下罰鍰，工商廠、場處十萬元以上五百萬元以下罰鍰，並得逕行拆除其污染源設備","處二十萬元以上一百萬元以下罰鍰，工商廠、場處一百萬元以上一千萬元以下罰鍰，並移送司法機關偵辦"],"a",
 "第63條：公私場所未依第24條第1項或第2項規定取得許可證，逕行設置、變更或操作者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上二千萬元以下罰鍰，並令停工及限期申請取得設置或操作許可證。若已取得許可證而未依許可證內容設置或操作者，則依第62條第1項第5款處罰。",
 "How is installing or operating a source without a permit punished?",
 ["NT$20,000 to NT$1 million, or NT$100,000 to NT$20 million for plants, plus shutdown and a deadline to obtain the permit","NT$20,000 to NT$1 million, or NT$100,000 to NT$20 million for plants, but no shutdown may be ordered, only correction","NT$1,200 to NT$100,000, or NT$100,000 to NT$5 million for plants, and the equipment may be dismantled by the authority","NT$200,000 to NT$1 million, or NT$1 million to NT$10 million for plants, with the case referred for criminal prosecution"],
 "Article 63; compare Article 62(1)(5)."),

(AP,"第64條",2,"空污法-罰則",
 "違反燃料使用許可證或易致空氣污染物質使用許可證之許可條件、記錄、申報規定者，如何處罰？",
 ["處二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰，並通知限期補正或申報，屆期未遵行者按次處罰","處二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰，並應於處分同時廢止其使用許可證","處五千元以上二十萬元以下罰鍰，工商廠、場處十萬元以上一百萬元以下罰鍰，且不得按次處罰或令其停工停業","處十萬元以上二百萬元以下罰鍰，不分公私場所或工商廠、場，並得逕行移送司法機關依虛偽記載罪偵辦"],"a",
 "第64條：公私場所違反第28條第1項或其辦法有關使用許可證之許可條件、記錄、申報及管理事項之規定，或違反第29條第1項或其辦法之相同事項者，處新臺幣二萬元以上一百萬元以下罰鍰；工商廠、場處十萬元以上二千萬元以下罰鍰，並通知限期補正或申報，屆期仍未遵行者按次處罰；情節重大者得令停工或停業，必要時並得廢止其使用許可或勒令歇業。",
 "How are breaches of fuel or hazardous substance use permits punished?",
 ["NT$20,000 to NT$1 million, or NT$100,000 to NT$20 million for plants, with notice to correct or report and repeated fines","NT$20,000 to NT$1 million, or NT$100,000 to NT$20 million for plants, and the use permit is revoked along with the fine","NT$5,000 to NT$200,000, or NT$100,000 to NT$1 million for plants, with no repeated fines, shutdown or suspension allowed","NT$100,000 to NT$2 million for all premises alike, with the case referred for prosecution for false record keeping"],
 "Article 64."),

(AP,"第65條",2,"空污法-罰則",
 "違反空氣品質嚴重惡化時之緊急防制措施規定者，公私場所與交通工具使用人之罰鍰各為何？",
 ["公私場所處二萬元以上一百萬元以下、工商廠場處十萬元以上二千萬元以下罰鍰；交通工具使用人或所有人處一千五百元以上三萬元以下罰鍰","公私場所處十萬元以上一百萬元以下、工商廠場處二十萬元以上五百萬元以下罰鍰；交通工具使用人或所有人處五百元以上六萬元以下罰鍰","公私場所處五千元以上十萬元以下、工商廠場處二萬元以上一百萬元以下罰鍰；交通工具使用人或所有人處三千元以上十萬元以下罰鍰","公私場所處二十萬元以上二百萬元以下、工商廠場處五十萬元以上一千萬元以下罰鍰；交通工具使用人或所有人免予處罰"],"a",
 "第65條：公私場所違反第14條第1項或依同條第4項所定辦法中有關採取緊急防制措施之管理規定者，處新臺幣二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰，情節重大者並得令停工或停業；違反該辦法中有關禁止或限制交通工具使用之管理規定者，處交通工具使用人或所有人新臺幣一千五百元以上三萬元以下罰鍰。",
 "What fines apply to premises and vehicle users for breaching emergency control measures?",
 ["Premises NT$20,000 to NT$1 million and plants NT$100,000 to NT$20 million; vehicle users or owners NT$1,500 to NT$30,000","Premises NT$100,000 to NT$1 million and plants NT$200,000 to NT$5 million; vehicle users or owners NT$500 to NT$60,000","Premises NT$5,000 to NT$100,000 and plants NT$20,000 to NT$1 million; vehicle users or owners NT$3,000 to NT$100,000","Premises NT$200,000 to NT$2 million and plants NT$500,000 to NT$10 million; vehicle users or owners are not fined at all"],
 "Article 65."),

(AP,"第66條",2,"空污法-罰則",
 "移動污染源使用人違反排放標準或防制設備規定，以及製造商安裝減效裝置，罰鍰各為何？",
 ["使用人或所有人處一千五百元以上六萬元以下罰鍰並限期改善；製造者或進口商按每輛汽車處十萬元以上五百萬元以下罰鍰並撤銷審驗合格證明","使用人或所有人處五百元以上一萬五千元以下罰鍰並限期改善；製造者或進口商按每輛汽車處一萬元以上十萬元以下罰鍰並命其限期召回","使用人或所有人處三千元以上十萬元以下罰鍰並吊扣牌照；製造者或進口商處五十萬元以上一千萬元以下罰鍰並停止其進口業務","使用人或所有人處一千五百元以上六萬元以下罰鍰並吊銷駕照；製造者或進口商按每輛汽車處五千元以上二十萬元以下罰鍰並公布名稱"],"a",
 "第66條：違反第36條第1項排放標準或第37條第1項防制設備規定者，處使用人或所有人新臺幣一千五百元以上六萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者按次處罰；製造者或進口商違反第36條第5項禁止安裝減效裝置規定者，按每輛汽車處新臺幣十萬元以上五百萬元以下罰鍰，並撤銷其汽車車型排氣審驗合格證明。施行細則第27條規定第2項之處罰由中央主管機關為之。",
 "What fines apply to mobile source users and to makers fitting defeat devices?",
 ["Users or owners NT$1,500 to NT$60,000 with a correction deadline; makers or importers NT$100,000 to NT$5 million per car and loss of type approval","Users or owners NT$500 to NT$15,000 with a correction deadline; makers or importers NT$10,000 to NT$100,000 per car and an order to recall","Users or owners NT$3,000 to NT$100,000 and plate suspension; makers or importers NT$500,000 to NT$10 million and suspension of imports","Users or owners NT$1,500 to NT$60,000 and licence revocation; makers or importers NT$5,000 to NT$200,000 per car and public naming"],
 "Article 66; Enforcement Rules Article 27."),

(AP,"第67條",2,"空污法-罰則",
 "違反第三十二條第一項各款空氣污染行為者，其罰鍰及後續處分為何？",
 ["處一千二百元以上十萬元以下罰鍰，工商廠、場處十萬元以上五百萬元以下罰鍰；並限期改善，情節重大者得令停止作為或停工停業","處一千五百元以上六萬元以下罰鍰，工商廠、場處二萬元以上一百萬元以下罰鍰；並限期改善，情節重大者得移送司法機關偵辦","處二萬元以上一百萬元以下罰鍰，工商廠、場處十萬元以上二千萬元以下罰鍰；並應逕行廢止其操作許可證及勒令歇業","處五百元以上一萬五千元以下罰鍰，工商廠、場處五千元以上二十萬元以下罰鍰；且不得通知限期改善或按次處罰"],"a",
 "第67條：違反第32條第1項各款情形之一者，處新臺幣一千二百元以上十萬元以下罰鍰；其違反者為工商廠、場，處十萬元以上五百萬元以下罰鍰；並通知限期改善，屆期仍未完成改善者按次處罰；情節重大者，得令其停止作為或污染源之操作，或令停工或停業，必要時並得廢止其操作許可或勒令歇業。不遵行停止作為或停止操作命令者依第56條第2項處刑罰。",
 "What fine and follow-up measures apply to prohibited air polluting acts?",
 ["NT$1,200 to NT$100,000, or NT$100,000 to NT$5 million for plants; plus a correction deadline and, in serious cases, stop-act or shutdown orders","NT$1,500 to NT$60,000, or NT$20,000 to NT$1 million for plants; plus a correction deadline and referral for prosecution in serious cases","NT$20,000 to NT$1 million, or NT$100,000 to NT$20 million for plants; with the operating permit revoked and the business closed at once","NT$500 to NT$15,000, or NT$5,000 to NT$200,000 for plants; with no notice to correct and no repeated penalties being permitted"],
 "Article 67; see Article 56(2) for defiance."),

(AP,"第68條",2,"空污法-罰則",
 "違反國際環保公約管制物質辦法中有關製造、販賣或使用之許可、記錄、申報規定者，如何處罰？",
 ["處十萬元以上二百萬元以下罰鍰，並通知限期補正或申報，屆期未遵行者按次處罰；情節重大者得令停工或停業","處六月以上五年以下有期徒刑，得併科三十萬元以上一百五十萬元以下罰金，並沒入其製造販賣之物質","處一千二百元以上十萬元以下罰鍰，並通知限期改善，屆期未改善者按次處罰，但不得廢止其販賣許可","處二十萬元以上一百萬元以下罰鍰，並應逕行廢止其許可，且不得通知限期補正或申報後再行裁處"],"a",
 "第68條：違反第31條第2項所定辦法有關製造、販賣或使用之許可、記錄、申報及管理事項之規定者，處新臺幣十萬元以上二百萬元以下罰鍰，並通知限期補正或申報，屆期仍未遵行者按次處罰；情節重大者得令其停工或停業，必要時並得廢止其販賣或使用許可或勒令歇業。若違反輸入或輸出限制規定，則依第52條科處自由刑。",
 "How are breaches of permit, record and reporting rules for treaty substances punished?",
 ["A fine of NT$100,000 to NT$2 million, with notice to correct or report, repeated fines, and shutdown in serious cases","Six months to five years imprisonment with a fine of NT$300,000 to NT$1.5 million and confiscation of the substances","A fine of NT$1,200 to NT$100,000 with notice to correct and repeated fines, but the sales permit may not be revoked","A fine of NT$200,000 to NT$1 million with immediate revocation of the permit and no notice to correct beforehand"],
 "Article 68; compare Article 52."),

(AP,"第69條",2,"空污法-罰則",
 "公私場所未設置專責單位或人員、未依規定公開資訊者，以及專責人員違反訓練規定者，罰鍰各為何？",
 ["公私場所處二十萬元以上二百萬元以下罰鍰並限期補正改善；專責人員處一萬元以上十萬元以下罰鍰，必要時中央主管機關得廢止其資格","公私場所處二萬元以上一百萬元以下罰鍰並限期補正改善；專責人員處五千元以上五萬元以下罰鍰，必要時地方主管機關得廢止其資格","公私場所處十萬元以上二千萬元以下罰鍰並令其停工；專責人員處二十萬元以上一百萬元以下罰鍰並終身不得再任專責人員","公私場所處五千元以上二十萬元以下罰鍰並公布名稱；專責人員免予處罰，僅由中央主管機關令其重新參加訓練"],"a",
 "第69條：公私場所違反第34條第1項、第2項專責單位或人員設置規定，或違反第35條第1項資訊公開規定者，處新臺幣二十萬元以上二百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者按次處罰；空氣污染防制專責人員及健康風險評估專責人員違反訓練及執行業務規定者，處一萬元以上十萬元以下罰鍰，必要時中央主管機關並得廢止其專責人員之資格。",
 "What fines apply for missing dedicated personnel or disclosure, and for personnel breaches?",
 ["Premises NT$200,000 to NT$2 million with a correction deadline; personnel NT$10,000 to NT$100,000 and the centre may revoke their qualification","Premises NT$20,000 to NT$1 million with a correction deadline; personnel NT$5,000 to NT$50,000 and the local authority may revoke qualification","Premises NT$100,000 to NT$20 million plus a shutdown order; personnel NT$200,000 to NT$1 million and a lifetime bar from serving again","Premises NT$5,000 to NT$200,000 and public naming; personnel are not fined and are merely ordered to attend the training again"],
 "Article 69."),

(AP,"第70條",2,"空污法-罰則",
 "檢驗測定機構未取得許可證即辦理檢驗測定，或違反相關管理規定者，如何處罰？",
 ["處二十萬元以上一百萬元以下罰鍰，並通知限期補正或改善，屆期未完成者按次處罰；情節重大者得令停業並廢止其許可","處二萬元以上一百萬元以下罰鍰，並通知限期補正或改善，屆期未完成者移送司法機關依偽造文書罪偵辦處理","處十萬元以上二千萬元以下罰鍰，並應逕行廢止其許可證及勒令歇業，不得先行通知限期補正或改善","處一千五百元以上六萬元以下罰鍰，並由中央主管機關公布其名稱，但不得令其停業或廢止其許可證"],"a",
 "第70條：違反第49條第1項未取得許可證辦理檢驗測定，或違反第49條第2項所定辦法有關檢驗測定機構應具備之條件、設施、人員資格、許可內容及管理事項之規定者，處新臺幣二十萬元以上一百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者按次處罰；情節重大者，得令其停業，必要時並得廢止其許可或勒令歇業。施行細則第27條規定本條處罰由中央主管機關為之。",
 "How is a testing organization punished for operating without or breaching its licence?",
 ["NT$200,000 to NT$1 million, with notice to correct, repeated fines, and in serious cases suspension and revocation of the licence","NT$20,000 to NT$1 million, with notice to correct, and referral to prosecutors for document forgery if not corrected in time","NT$100,000 to NT$20 million, with immediate revocation of the licence and closure, without any prior notice to correct","NT$1,500 to NT$60,000, with the name published by the central authority, but no suspension or revocation of the licence"],
 "Article 70; Enforcement Rules Article 27."),

(AP,"第71條",2,"空污法-罰則",
 "規避、妨礙或拒絕主管機關之檢查、鑑定或命令者，公私場所與移動污染源之罰鍰各為何？",
 ["公私場所處二十萬元以上一百萬元以下罰鍰；移動污染源使用人或所有人處五千元以上十萬元以下罰鍰，並得按次處罰及強制執行檢查","公私場所處二萬元以上一百萬元以下罰鍰；移動污染源使用人或所有人處一千五百元以上六萬元以下罰鍰，但不得強制執行檢查鑑定","公私場所處十萬元以上二千萬元以下罰鍰；移動污染源使用人或所有人處二萬元以上二十萬元以下罰鍰，並得逕行吊扣其汽車牌照","公私場所處五千元以上二十萬元以下罰鍰；移動污染源使用人或所有人免予處罰，僅得通知其限期至指定地點接受檢驗"],"a",
 "第71條：規避、妨礙或拒絕依第48條第1項之檢查、鑑定或命令，或未依第48條第4項具備便於檢查鑑定之設施者，處公私場所新臺幣二十萬元以上一百萬元以下罰鍰；處移動污染源使用人或所有人新臺幣五千元以上十萬元以下罰鍰，並得按次處罰及強制執行檢查、鑑定。施行細則第27條規定本條處罰由中央及地方主管機關分別為之。",
 "What fines apply for evading or refusing inspection by the authority?",
 ["Premises NT$200,000 to NT$1 million; mobile source users or owners NT$5,000 to NT$100,000, with repeated fines and compulsory inspection","Premises NT$20,000 to NT$1 million; mobile source users or owners NT$1,500 to NT$60,000, but inspection may not be compelled at all","Premises NT$100,000 to NT$20 million; mobile source users or owners NT$20,000 to NT$200,000, with immediate suspension of the plate","Premises NT$5,000 to NT$200,000; mobile source users or owners are not fined and are merely summoned for testing by a deadline"],
 "Article 71."),

(AP,"第72條",2,"空污法-罰則",
 "違反含揮發性有機物化學製品成分標準者，對何人處罰？罰鍰額度為何？",
 ["處製造、進口或販賣者新臺幣十萬元以上一百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰","處製造或進口者新臺幣二萬元以上一百萬元以下罰鍰，販賣者及使用者則免予處罰，亦不通知限期改善","處使用該化學製品之公私場所新臺幣二十萬元以上二百萬元以下罰鍰，並得令其停工或廢止操作許可","處製造、進口或販賣者新臺幣一千二百元以上十萬元以下罰鍰，並得沒入其產品，不通知限期改善"],"a",
 "第72條：違反第47條第1項規定者，處製造、進口或販賣者新臺幣十萬元以上一百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰。第47條規定製造、進口、販賣經中央主管機關指定公告含揮發性有機物之化學製品，應符合該製品之含揮發性有機物成分標準，專供出口者不在此限。",
 "Who is fined for breaching the VOC content standard for chemical products, and how much?",
 ["Makers, importers or sellers face NT$100,000 to NT$1 million, with notice to correct and repeated fines if not corrected in time","Makers or importers face NT$20,000 to NT$1 million while sellers and users are not fined and no correction notice is issued","The premises using the product face NT$200,000 to NT$2 million, and may be ordered to shut down or lose the operating permit","Makers, importers or sellers face NT$1,200 to NT$100,000 and the products may be confiscated, with no notice to correct given"],
 "Article 72; see Article 47."),

(AP,"第73條",2,"空污法-罰則",
 "違反移動污染源用燃料種類及成分標準者，對製造販賣進口者及使用人之罰鍰各為何？",
 ["製造、販賣或進口者處十萬元以上一百萬元以下罰鍰並限期改善；使用人處五千元以上十萬元以下罰鍰","製造、販賣或進口者處二萬元以上二十萬元以下罰鍰並限期改善；使用人處一千五百元以上三萬元以下罰鍰","製造、販賣或進口者處二十萬元以上二百萬元以下罰鍰並停業；使用人處二萬元以上二十萬元以下罰鍰","製造、販賣或進口者處十萬元以上一百萬元以下罰鍰並勒令歇業；使用人免罰但應限期更換合格燃料"],"a",
 "第73條：違反第39條第1項或第2項規定，或違反第39條第3項所定辦法有關販賣、進口之許可內容、記錄、申報及管理事項之規定者，處製造、販賣或進口者新臺幣十萬元以上一百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰；違反第39條第1項規定者，處使用人新臺幣五千元以上十萬元以下罰鍰。",
 "What fines apply to makers, sellers or importers and to users of non-compliant fuel?",
 ["Makers, sellers or importers NT$100,000 to NT$1 million with a correction deadline; users NT$5,000 to NT$100,000","Makers, sellers or importers NT$20,000 to NT$200,000 with a correction deadline; users NT$1,500 to NT$30,000","Makers, sellers or importers NT$200,000 to NT$2 million plus suspension; users NT$20,000 to NT$200,000 in fines","Makers, sellers or importers NT$100,000 to NT$1 million plus closure; users are not fined but must switch fuel"],
 "Article 73."),

(AP,"第74條",3,"空污法-滯納金",
 "未於期限內繳納空氣污染防制費者，其滯納金及罰鍰如何計算？",
 ["每逾一日按滯納金額加徵百分之零點五滯納金；逾期三十日仍未申報或繳納者處一千五百元以上六萬元以下罰鍰，工商廠場處十萬元以上一百萬元以下","每逾一日按滯納金額加徵百分之五滯納金；逾期十五日仍未申報或繳納者處五千元以上十萬元以下罰鍰，工商廠場處二十萬元以上二百萬元以下","每逾一日按滯納金額加徵百分之一滯納金；逾期六十日仍未申報或繳納者處二萬元以上一百萬元以下罰鍰，工商廠場處五十萬元以上五百萬元以下","每逾一月按滯納金額加徵百分之零點五滯納金；逾期九十日仍未申報或繳納者處三千元以上三萬元以下罰鍰，工商廠場處五萬元以上五十萬元以下"],"a",
 "第74條：未依第16條第2項所定辦法於期限內繳納費用者，每逾一日按滯納之金額加徵百分之零點五滯納金，一併繳納；逾期三十日仍未申報或繳納者，處新臺幣一千五百元以上六萬元以下罰鍰，其為工商廠、場者處十萬元以上一百萬元以下罰鍰，並限期繳納；應繳納費用應自滯納期限屆滿之次日至繳納之日止，依繳納當日郵政儲金一年期定期存款固定利率按日加計利息。",
 "How are late payment surcharges and fines for the air pollution fee calculated?",
 ["0.5% of the overdue amount per day; after 30 days of non-payment NT$1,500 to NT$60,000, or NT$100,000 to NT$1 million for plants","5% of the overdue amount per day; after 15 days of non-payment NT$5,000 to NT$100,000, or NT$200,000 to NT$2 million for plants","1% of the overdue amount per day; after 60 days of non-payment NT$20,000 to NT$1 million, or NT$500,000 to NT$5 million for plants","0.5% of the overdue amount per month; after 90 days NT$3,000 to NT$30,000, or NT$50,000 to NT$500,000 for industrial plants"],
 "Article 74."),

(AP,"第75條",3,"空污法-逃漏費",
 "公私場所以不正當方式短報或漏報空氣污染防制費計算資料者，主管機關如何計算應繳費額及追溯？",
 ["移動污染源、營建工程及其他固定污染源均依各該收費費率或核算排放量之二倍計算應繳費額，並追溯五年內之應繳費額","移動污染源依收費費率之三倍計算，營建工程依五倍計算，其他固定污染源依十倍計算，並追溯三年內之應繳費額","一律依原收費費率計算應繳費額，不予加倍，但應追溯十年內之應繳費額並按日加計滯納金及利息","由主管機關逕行處以罰鍰而不補徵費額，亦不追溯過往年度之應繳費額，僅命其限期改善申報方式"],"a",
 "第75條：公私場所有偽造、變造或其他不正當方式短報或漏報與空氣污染防制費計算有關資料者，移動污染源得逕依收費費率之二倍計算應繳費額，營建工程得逕依查驗結果或相關資料以收費費率之二倍計算，營建工程以外固定污染源得逕依排放係數或質量平衡核算排放量之二倍計算；並追溯五年內之應繳費額，但起徵未滿五年者自起徵日起算；追溯費額應按日加計利息。",
 "How is the fee recalculated and how far back is it traced for under-reporting?",
 ["Mobile sources, construction projects and other stationary sources are all charged at twice the rate or calculated emissions, traced back five years","Mobile sources are charged three times the rate, construction projects five times and other stationary sources ten times, traced back three years","The original rate applies with no multiplier, but the fee is traced back ten years with daily surcharges and interest added on top","The authority imposes a fine without recovering the fee and does not trace past years, merely ordering the reporting to be corrected"],
 "Article 75."),

(AP,"第76條",2,"空污法-罰則",
 "違反怠速停車限制及空氣品質維護區管制措施者，罰鍰額度各為何？",
 ["違反怠速限制處汽車使用人或所有人一千五百元以上六萬元以下；違反維護區管制措施處汽車使用人或所有人五百元以上六萬元以下，其他移動污染源處五千元以上一百萬元以下","違反怠速限制處汽車使用人或所有人五百元以上一萬五千元以下；違反維護區管制措施處汽車使用人或所有人一千五百元以上三萬元以下，其他移動污染源處一萬元以上十萬元以下","違反怠速限制處汽車使用人或所有人三千元以上六萬元以下；違反維護區管制措施處汽車使用人或所有人二萬元以上十萬元以下，其他移動污染源處十萬元以上五百萬元以下","違反怠速限制處汽車製造者一千五百元以上六萬元以下；違反維護區管制措施處汽車製造者五百元以上六萬元以下，其他移動污染源之所有人則一律免予處罰"],"a",
 "第76條：違反第38條第2項所定辦法有關怠速停車限制之規定者，處汽車使用人或所有人新臺幣一千五百元以上六萬元以下罰鍰，並得令其改善，未改善者按次處罰至改善為止；違反第40條第3項地方主管機關公告之移動污染源管制措施者，處汽車使用人或所有人新臺幣五百元以上六萬元以下罰鍰，處汽車以外其他移動污染源使用人、所有人新臺幣五千元以上一百萬元以下罰鍰。",
 "What fines apply for breaching idling limits and maintenance area controls?",
 ["Idling: car users or owners NT$1,500 to NT$60,000; maintenance area: car users or owners NT$500 to NT$60,000 and other mobile sources NT$5,000 to NT$1 million","Idling: car users or owners NT$500 to NT$15,000; maintenance area: car users or owners NT$1,500 to NT$30,000 and other mobile sources NT$10,000 to NT$100,000","Idling: car users or owners NT$3,000 to NT$60,000; maintenance area: car users or owners NT$20,000 to NT$100,000 and other mobile sources NT$100,000 to NT$5 million","Idling: car makers NT$1,500 to NT$60,000; maintenance area: car makers NT$500 to NT$60,000, while owners of other mobile sources are never fined at all"],
 "Article 76."),

(AP,"第77條",2,"空污法-罰則",
 "製造者或進口商不遵行限期召回改正命令者，以及違反召回改正辦法管理規定者，罰鍰各為何？",
 ["不遵行召回改正命令者按每輛汽車處新臺幣十萬元罰鍰；違反召回改正辦法管理規定者處五千元以上二十萬元以下罰鍰並限期補正改善","不遵行召回改正命令者按每輛汽車處新臺幣一萬元罰鍰；違反召回改正辦法管理規定者處一千五百元以上六萬元以下罰鍰並限期補正改善","不遵行召回改正命令者按每輛汽車處新臺幣五十萬元罰鍰；違反召回改正辦法管理規定者處十萬元以上一百萬元以下罰鍰並命其停止進口","不遵行召回改正命令者處新臺幣一百萬元以上一千萬元以下罰鍰；違反召回改正辦法管理規定者僅命其限期補正，不另處罰鍰或按次處罰"],"a",
 "第77條：製造者或進口商違反第41條第1項規定，不遵行中央主管機關限期召回改正之命令者，按每輛汽車處新臺幣十萬元罰鍰；違反第41條第2項所定辦法有關召回改正之管理規定者，處新臺幣五千元以上二十萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者按次處罰。第41條並定明屆期仍不遵行者應停止其製造、進口及銷售。",
 "What fines apply for defying a recall order and for breaching recall regulations?",
 ["Defying a recall order: NT$100,000 per vehicle; breaching the recall regulations: NT$5,000 to NT$200,000 with a correction deadline","Defying a recall order: NT$10,000 per vehicle; breaching the recall regulations: NT$1,500 to NT$60,000 with a correction deadline","Defying a recall order: NT$500,000 per vehicle; breaching the recall regulations: NT$100,000 to NT$1 million and a ban on imports","Defying a recall order: NT$1 million to NT$10 million; breaching the recall regulations brings only a correction notice, no fine"],
 "Article 77."),

(AP,"第78條",2,"空污法-罰則",
 "違反車型排氣審驗合格證明核發管理規定，或交通工具排放檢驗處理管理規定者，如何處罰？",
 ["處新臺幣五千元以上二十萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者按次處罰","處新臺幣一千五百元以上六萬元以下罰鍰，並通知限期改善，屆期未完成改善者移送司法機關偵辦","處新臺幣十萬元以上一百萬元以下罰鍰，並應逕行撤銷其車型排氣審驗合格證明，不通知限期補正","處新臺幣二十萬元以上二百萬元以下罰鍰，並命其停止製造及進口，屆期未改善者廢止其公司登記"],"a",
 "第78條：違反依第42條第2項所定辦法有關汽車車型排氣審驗合格證明之核發及管理事項之規定，或違反第43條第2項所定辦法有關交通工具排放空氣污染物之檢驗、處理管理事項之規定者，處新臺幣五千元以上二十萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者按次處罰。施行細則第27條規定第1款由中央主管機關處罰，第2款由地方主管機關處罰。",
 "How are breaches of type approval or vehicle inspection regulations punished?",
 ["A fine of NT$5,000 to NT$200,000, with notice to correct and repeated fines if not corrected within the period","A fine of NT$1,500 to NT$60,000, with notice to correct and referral for prosecution if not corrected in time","A fine of NT$100,000 to NT$1 million, with the type approval certificate revoked at once and no correction notice","A fine of NT$200,000 to NT$2 million, with manufacture and import halted and company registration revoked"],
 "Article 78; Enforcement Rules Article 27."),

(AP,"第79條",2,"空污法-罰則",
 "移動污染源不依規定接受不定期檢驗或遙測後檢驗，或經檢驗不符合排放標準者，如何處罰？",
 ["處移動污染源使用人或所有人一千五百元以上六萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰","處移動污染源使用人或所有人五百元以上一萬五千元以下罰鍰，並得逕行移請公路監理機關註銷其牌照","處移動污染源使用人或所有人五千元以上十萬元以下罰鍰，並強制執行檢驗，不通知限期改善或按次處罰","處移動污染源製造者或進口商十萬元以上五百萬元以下罰鍰，使用人或所有人則免罰，僅通知限期受檢"],"a",
 "第79條：不依第45條第1項、第46條第1項、第2項規定檢驗，或經檢驗不符合排放標準者，處移動污染源使用人或所有人新臺幣一千五百元以上六萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰。第45條為不定期檢驗，第46條為目測、目視或遙測不符標準及檢舉車輛應受檢之規定。",
 "How is failing an unscheduled inspection or refusing to be tested punished?",
 ["The user or owner faces NT$1,500 to NT$60,000, with notice to correct and repeated fines if not corrected in time","The user or owner faces NT$500 to NT$15,000, and the licence plate may be cancelled through the motor vehicle office","The user or owner faces NT$5,000 to NT$100,000 with compulsory testing, and no correction notice or repeated fines","The maker or importer faces NT$100,000 to NT$5 million while users and owners are merely summoned to be tested"],
 "Article 79; see Articles 45 and 46."),

(AP,"第80條",2,"空污法-定期檢驗罰則",
 "汽車未實施定期檢驗，或經定期檢驗不合格未於期限內修復複驗者，罰鍰各為何？",
 ["未實施定期檢驗者處汽車所有人五百元以上一萬五千元以下罰鍰；未於一個月內修復複驗或複驗不合格者處一千五百元以上三萬元以下罰鍰","未實施定期檢驗者處汽車所有人一千五百元以上六萬元以下罰鍰；未於一個月內修復複驗或複驗不合格者處三千元以上六萬元以下罰鍰","未實施定期檢驗者處汽車所有人三千元以上三萬元以下罰鍰；未於三個月內修復複驗或複驗不合格者處五千元以上十萬元以下罰鍰","未實施定期檢驗者處汽車製造者五百元以上一萬五千元以下罰鍰；未於一個月內修復複驗者則免罰，僅通知限期改善"],"a",
 "第80條第1項、第2項：未依第44條第1項規定實施排放空氣污染物定期檢驗者，處汽車所有人新臺幣五百元以上一萬五千元以下罰鍰；經定期檢驗不符合排放標準之車輛，未於檢驗日起一個月內修復並複驗，或於期限屆滿後之複驗不合格者，處新臺幣一千五百元以上三萬元以下罰鍰。",
 "What fines apply for skipping periodic inspection or failing to repair and retest?",
 ["Skipping inspection: the owner faces NT$500 to NT$15,000; failing to repair and retest within a month: NT$1,500 to NT$30,000","Skipping inspection: the owner faces NT$1,500 to NT$60,000; failing to repair and retest within a month: NT$3,000 to NT$60,000","Skipping inspection: the owner faces NT$3,000 to NT$30,000; failing to repair and retest within three months: NT$5,000 to NT$100,000","Skipping inspection: the maker faces NT$500 to NT$15,000; failing to repair and retest within a month brings only a correction notice"],
 "Article 80, paragraphs 1 and 2."),

(AP,"第80條",3,"空污法-註銷牌照",
 "逾應檢驗日起多久仍未實施定期檢驗或複驗不合格，經二次限期改善仍未改善者，會有何後果？",
 ["逾六個月者經通知限期改善屆期未改善處三千元以上六萬元以下罰鍰；再通知限期改善仍未改善者得移請公路監理機關註銷其牌照","逾三個月者經通知限期改善屆期未改善處五千元以上十萬元以下罰鍰；再通知限期改善仍未改善者得移請公路監理機關吊扣其牌照","逾一年者經通知限期改善屆期未改善處一千五百元以上三萬元以下罰鍰；再通知限期改善仍未改善者得逕行命其報廢該車輛","逾六個月者即由主管機關逕行註銷牌照，無須通知限期改善，亦不另處罰鍰或給予任何補正改善之機會"],"a",
 "第80條第3項：逾應檢驗日起六個月仍未實施定期檢驗、未依規定申請複驗或複驗仍不合格者，經直轄市、縣（市）主管機關通知限期改善，屆期未完成改善者，處新臺幣三千元以上六萬元以下罰鍰；經再通知限期改善，屆期仍未完成改善者，得移請公路監理機關註銷其牌照。第4項另定違反檢驗站設置管理規定者處一萬五千元以上六萬元以下罰鍰。第84條並定明拒不繳納罰鍰者得停止車輛異動。",
 "What follows six months of missed periodic inspection after two correction notices?",
 ["A fine of NT$3,000 to NT$60,000 after the first notice; if still uncorrected after a second, the licence plate may be cancelled","A fine of NT$5,000 to NT$100,000 after the first notice at three months; if still uncorrected, the plate may be suspended","A fine of NT$1,500 to NT$30,000 after a year and a first notice; if still uncorrected, the vehicle may be ordered scrapped","The authority cancels the plate directly at six months with no correction notice, no fine and no chance to put things right"],
 "Article 80, paragraphs 3 and 4; see also Article 84."),

(AP,"第81條",2,"空污法-改善認定",
 "依本法通知改善者，未於期限屆滿前檢具何種文件報請查驗，將視為未完成改善？",
 ["未檢具已規劃設置緩衝地帶及監測設施、符合排放標準、燃料成分標準或含揮發性有機物成分標準等證明文件報請查驗者","未檢具繳清空氣污染防制費及罰鍰之證明文件，或未提出經技師簽證之改善計畫書報請主管機關查驗核備者","未檢具環境影響評估審查結論及目的事業主管機關同意文件，並報請中央主管機關派員實地查驗合格者","未檢具停工期間之操作紀錄及專責人員名冊，並於期限屆滿後三十日內補送主管機關備查存檔者"],"a",
 "第81條：未於依本法通知改善之期限屆滿前，檢具已規劃、設置緩衝地帶及空氣品質監測設施、符合排放標準、燃料成分標準、含揮發性有機物化學製品成分標準或其他規定之證明文件，向直轄市、縣（市）主管機關報請查驗者，視為未完成改善；限期改善或補正之期限、改善完成認定查驗方式等準則由中央主管機關定之。",
 "What omission means improvement is deemed not completed?",
 ["Failing to file proof of planned buffer zones and monitors, or of meeting emission, fuel or VOC content standards, for verification","Failing to file proof that fees and fines are paid, or an improvement plan certified by an engineer, for the authority to verify","Failing to file the EIA conclusion and industry authority consent and to pass an on-site central inspection within the period","Failing to file operating records and the personnel roster during shutdown within thirty days after the deadline expires"],
 "Article 81."),

(AP,"第82條",3,"空污法-改善期限",
 "依本法通知限期補正、改善或申報者，其期間以多久為限？因天災不可抗力時如何處理？",
 ["以九十日為限；因天災或不可抗力致未能完成者，應於原因消滅後繼續改善，並於十五日內以書面敘明理由申請核定改善期限","以三十日為限；因天災或不可抗力致未能完成者，應於原因消滅後繼續改善，並於七日內以書面敘明理由申請核定改善期限","以一百八十日為限；因天災或不可抗力致未能完成者，得逕行延長一年，無須向主管機關申請核定其改善期限","以六十日為限；因天災或不可抗力致未能完成者，應於原因消滅後三個月內申請核定，逾期即視為未完成改善"],"a",
 "第82條第1項：依本法通知限期補正、改善或申報者，其補正、改善或申報期間，以九十日為限；因天災或其他不可抗力事由致未能於改善期限內完成改善者，應於其原因消滅後繼續進行改善，並於十五日內以書面敘明理由，檢具相關資料，向各級主管機關申請核定改善期限。",
 "How long is the correction period, and what applies in force majeure?",
 ["Ninety days at most; in force majeure, resume once the cause ends and apply in writing within fifteen days for a new deadline","Thirty days at most; in force majeure, resume once the cause ends and apply in writing within seven days for a new deadline","One hundred eighty days at most; in force majeure it extends by one year automatically with no application to the authority","Sixty days at most; in force majeure apply within three months after the cause ends, or improvement is deemed incomplete"],
 "Article 82, paragraph 1."),

(AP,"第82條",3,"空污法-展延改善",
 "公私場所未能於九十日改善期限內完成改善者，得如何申請延長？延長期限上限為何？",
 ["得於接獲通知之日起三十日內提出具體改善計畫申請延長，主管機關依實際狀況核定，最長以一年為限，必要時得再延長一年","得於接獲通知之日起十五日內提出具體改善計畫申請延長，主管機關依實際狀況核定，最長以六個月為限且不得再延長","得於改善期限屆滿後六十日內提出改善計畫申請延長，主管機關應一律核定二年之改善期限，並免除期間之處罰","得隨時以口頭方式向主管機關申請延長改善期限，主管機關不得拒絕，且延長期間排放超標亦不予處罰"],"a",
 "第82條第2項、第3項：公私場所未能於九十日期限內完成改善者，得於接獲通知之日起三十日內提出具體改善計畫，向各級主管機關申請延長，各級主管機關應依實際狀況核定改善期限，最長以一年為限，必要時得再延長一年；未確實依改善計畫執行經查屬實者，得立即終止其改善期限並從重處罰。固定污染源及移動污染源於改善期間，排放之空氣污染物種類超過原據以處罰之排放濃度或排放量者，應按次處罰。",
 "How may the ninety-day improvement period be extended, and what is the cap?",
 ["File a concrete improvement plan within thirty days of the notice; the authority sets the period, capped at one year, extendable once more","File a concrete improvement plan within fifteen days of the notice; the period is capped at six months and may not be extended again","File an improvement plan within sixty days after the deadline; the authority must grant two years and waive penalties meanwhile","Apply orally at any time; the authority may not refuse, and exceedances during the extended period are not penalized at all"],
 "Article 82, paragraphs 2 and 3."),

(AP,"第83條",1,"空污法-處罰機關",
 "本法所定之處罰，在中央及地方分別由何機關為之？",
 ["在中央由行政院環境保護署為之；在直轄市、縣（市）由直轄市、縣（市）政府為之","在中央由行政院為之；在直轄市、縣（市）由各該環境保護局及公路監理機關為之","在中央由經濟部為之；在直轄市、縣（市）由直轄市、縣（市）建設主管機關為之","在中央由行政院環境保護署為之；在直轄市、縣（市）一律委由中央主管機關為之"],"a",
 "第83條：本法所定之處罰，在中央由行政院環境保護署為之；在直轄市、縣（市）由直轄市、縣（市）政府為之。施行細則第27條進一步分配各條處罰之權責機關，例如第66條第2項、第70條、第71條、第77條、第78條第1款由中央主管機關為之，第58條至第65條等由地方主管機關為之。",
 "Which bodies impose penalties at central and local level?",
 ["At central level the EPA of the Executive Yuan; at local level the municipal or county government concerned","At central level the Executive Yuan; at local level the environmental bureau and the motor vehicle office","At central level the Ministry of Economic Affairs; at local level the municipal or county works authority","At central level the EPA of the Executive Yuan; local penalties are all delegated back to the central authority"],
 "Article 83; Enforcement Rules Article 27."),

(AP,"第84條",2,"空污法-車輛異動",
 "汽車所有人或使用人拒不繳納罰鍰時，主管機關得採取何種措施？",
 ["得由直轄市、縣（市）主管機關移請公路監理機關配合停止其辦理車輛異動","得由直轄市、縣（市）主管機關逕行查封拍賣其車輛以抵繳應納之罰鍰金額","得由中央主管機關逕行註銷其汽車牌照及駕駛執照，並限制其出境或出海","得由直轄市、縣（市）主管機關移送司法機關依違反行政義務罪偵辦處理"],"a",
 "第84條：汽車所有人或使用人，拒不繳納罰鍰時，得由直轄市、縣（市）主管機關移請公路監理機關配合停止其辦理車輛異動。施行細則第28條定明所稱辦理車輛異動，指過戶、變更、停駛、復駛、報廢、繳銷牌照、註銷牌照及其他經交通主管機關規定之事項。",
 "What may the authority do when a vehicle owner refuses to pay a fine?",
 ["The local authority may ask the motor vehicle office to block registration changes for that vehicle","The local authority may seize and auction the vehicle directly to cover the unpaid fine amount","The central authority may cancel the plate and driving licence and bar the owner from leaving","The local authority may refer the case to prosecutors for breach of an administrative duty"],
 "Article 84; Enforcement Rules Article 28 lists the blocked changes."),

(AP,"第85條",2,"空污法-裁罰準則",
 "依本法處罰鍰者，其額度應依何種因素裁處？何種情形應從重處罰？",
 ["應依污染源種類、污染物項目、程度、特性及危害程度裁處；違規情節對學校有影響者應從重處罰","應依公私場所之資本額、營業額及員工人數裁處；違規情節對醫院有影響者應從重處罰","應依違規次數及改善進度裁處；違規情節對工業區內其他廠商有影響者應從重處罰","應依污染源所在地之地價及土地面積裁處；違規情節對農地有影響者應從重處罰"],"a",
 "第85條：依本法處罰鍰者，其額度應依污染源種類、污染物項目、程度、特性及危害程度裁處，其違規情節對學校有影響者，應從重處罰；裁罰之準則由中央主管機關定之。第86條另定違反本法義務行為有所得利益者，得於所得利益範圍內予以追繳。",
 "What factors set the fine amount, and when must it be aggravated?",
 ["Source type, pollutant, degree, characteristics and harm; aggravation applies where schools are affected by the violation","Capital, turnover and staff numbers of the premises; aggravation applies where hospitals are affected by the violation","Number of violations and progress of improvement; aggravation applies where other firms in the park are affected","Land value and area where the source is located; aggravation applies where farmland is affected by the violation"],
 "Article 85."),

(AP,"第86條",3,"空污法-追繳利益",
 "違反本法義務行為而有所得利益者，主管機關得如何處理？其利益範圍如何認定？",
 ["除裁處罰鍰外，並得於所得利益之範圍內予以追繳；利益包括積極利益及應支出而未支出或減少支出之消極利益","僅得裁處罰鍰而不得追繳所得利益；所得利益之計算僅限於實際增加之營業收入，不含節省之支出費用","得於所得利益二倍範圍內追繳並免除罰鍰；利益僅指違規期間之全部營業額，不論其是否為積極或消極利益","應移送司法機關沒收其犯罪所得，行政機關不得逕行追繳；利益範圍由法院依刑法沒收規定逐案認定之"],"a",
 "第86條：違反本法義務行為而有所得利益者，除應依本法規定裁處一定金額之罰鍰外，並得於所得利益之範圍內予以追繳；為他人利益而實施行為或他人因該行為受有財產上利益而未受處罰者，得於其所受財產上利益價值範圍內予以追繳；追繳由為裁處之各級主管機關以行政處分為之，所稱利益得包括積極利益及應支出而未支出或減少支出之消極利益，其核算及推估辦法由中央主管機關定之。",
 "How may unlawful gains from violating the Act be dealt with?",
 ["Besides the fine, they may be recovered up to the amount of the gain; gains include both positive gains and avoided or reduced expenditure","Only a fine may be imposed and unlawful gains may not be recovered; gains cover only added revenue and never any savings on expenditure","Twice the gain may be recovered in lieu of a fine; the gain means all turnover during the violation regardless of its nature","The case must go to court for confiscation of proceeds; the authority may not recover them and courts assess the scope"],
 "Article 86."),

(AP,"第87條",2,"空污法-基金來源",
 "各級主管機關設置之空氣污染防制特種基金，其來源除空氣污染防制費外還包括哪些？",
 ["交易或拍賣所得、依法追繳之所得利益、違反本法罰鍰之部分提撥、依本法科處繳納之罰金及沒收追徵之現金或變賣所得","公務預算編列之補助款、目的事業主管機關之產業輔導經費、民間捐贈及國際組織補助之空氣品質改善專案款項","土地增值稅及房屋稅之部分提撥、環境影響評估審查規費、檢驗測定機構之許可證費及公私場所之保證金孳息","空氣品質維護區之通行費收入、汽車燃料使用費之部分提撥、車輛牌照稅收入及交通違規罰鍰之全額移撥"],"a",
 "第87條：各級主管機關依第18條第2項設置之特種基金，其來源除第16條第1項徵收之空氣污染防制費外，應包括第9條第1項第2款交易或拍賣所得、依第86條追繳之所得利益、違反本法罰鍰之部分提撥、依本法科處並繳納之罰金及因違反本法規定沒收或追徵之現金或變賣所得。施行細則第29條定明罰鍰之部分提撥指實收罰鍰金額之百分之三十。",
 "Besides the pollution fee, what feeds the special air pollution control fund?",
 ["Trading or auction proceeds, recovered unlawful gains, a share of fines, criminal fines paid, and cash or proceeds confiscated","Budget subsidies, industry guidance funds from industry authorities, private donations and international grants for air quality","A share of land value and house taxes, EIA review fees, testing organization licence fees and interest on posted deposits","Toll income from maintenance areas, a share of the fuel use fee, licence plate tax revenue and all traffic fines collected"],
 "Article 87; Enforcement Rules Article 29 sets the share of fines at 30%."),

(AP,"第88條",2,"空污法-過渡規定",
 "指定公告前既已設立之固定污染源，應於何時申請操作許可證？",
 ["應自公告之日起二年內，依第二十四條第二項規定申請操作許可證","應自公告之日起六個月內，依第二十四條第一項規定申請設置許可證","應自公告之日起五年內，依第二十四條第二項規定申請操作許可證","應自本法施行之日起一年內，向中央主管機關申請核發操作許可證"],"a",
 "第88條：公私場所具有依第24條第1項指定公告之固定污染源，且該固定污染源係於公告前設立者，應自公告之日起二年內，依第24條第2項申請操作許可證。第30條並定明許可證有效期間為五年，展延應於屆滿前三至六個月內提出。",
 "By when must sources built before designation apply for an operating permit?",
 ["Within two years from the date of the announcement, under Article 24, paragraph 2","Within six months from the date of the announcement, under Article 24, paragraph 1","Within five years from the date of the announcement, under Article 24, paragraph 2","Within one year of the Act taking effect, applying to the central competent authority"],
 "Article 88."),

(AP,"第89條",3,"空污法-故障免罰",
 "固定污染源設施故障致違反本法規定時，公私場所應符合哪些條件始得免罰？",
 ["故障後一小時內向地方主管機關報備、二十四小時內修復或停止操作、十五日內提出書面報告，並立即採取因應措施","故障後二十四小時內向地方主管機關報備、七日內修復或停止操作、三十日內提出書面報告，並立即採取因應措施","故障後三日內向中央主管機關報備、十五日內修復或停止操作、六十日內提出書面報告，並立即採取因應措施","故障後立即停工並於三十日內報備、九十日內修復完成、一年內提出書面報告，並取得技師簽證之改善計畫"],"a",
 "第89條：固定污染源之相關設施故障致違反本法規定時，公私場所立即採取因應措施，並依下列規定處理者得免依本法處罰：一、故障發生後一小時內向直轄市、縣（市）主管機關報備。二、故障發生後二十四小時內修復或停止操作。三、故障發生後十五日內向直轄市、縣（市）主管機關提出書面報告。施行細則第30條定明故障指不可預見且無法避免之功能失效，因設計不當或操作維護不良者不適用；第31條、第32條並定明報備方式及書面報告內容。",
 "What conditions exempt a source from penalty when equipment malfunctions?",
 ["Report to the local authority within one hour, repair or stop operating within 24 hours, file a written report within 15 days, and act at once","Report to the local authority within 24 hours, repair or stop within 7 days, file a written report within 30 days, and act at once","Report to the central authority within 3 days, repair or stop within 15 days, file a written report within 60 days, and act at once","Shut down at once and report within 30 days, repair within 90 days, file a report within a year with a certified improvement plan"],
 "Article 89; Enforcement Rules Articles 30 to 32."),

(AP,"第90條",2,"空污法-免罰行為",
 "公私場所從事哪些行為，經逐案申請並經審查核可者，得免依本法處罰？",
 ["消防演練、緊急防止傳染病擴散而燃燒受感染之動植物、取得山林田野引火燃燒許可從事燃燒及其他經中央公告之行為","營建工程之夜間趕工、廢棄物露天焚燒、農業廢棄物就地燃燒及其他經直轄市、縣（市）主管機關核准之行為","歲修期間停止防制設施運轉、試車期間超標排放、緊急發電機測試及其他經目的事業主管機關同意之行為","民俗祭祀活動燃放爆竹、餐飲業戶外炭烤、露天堆置粉粒狀物及其他經中央主管機關備查之短期行為"],"a",
 "第90條：公私場所從事下列行為前，已逐案向直轄市、縣（市）主管機關申請並經審查核可者，免依本法處罰：一、消防演練。二、緊急防止傳染病擴散而燃燒受感染之動植物。三、取得山林田野引火燃燒許可從事燃燒者。四、其他經中央主管機關公告之行為。氣象條件不利於污染物擴散、空氣品質有明顯惡化之趨勢或未依核可內容實施時，主管機關得令暫緩或停止實施。施行細則第33條定明應檢具實施計畫及不予核可之情形。",
 "Which acts, if approved case by case in advance, escape penalty under the Act?",
 ["Fire drills, burning infected animals or plants to stop an epidemic, burning under an open field burning permit, and others announced centrally","Night-time construction rush work, open burning of waste, on-site burning of farm waste, and other acts approved by local authorities","Stopping control equipment during overhauls, exceedances during trial runs, generator testing, and other acts agreed by industry authorities","Setting off firecrackers at folk rituals, outdoor charcoal grilling, open stockpiling of granular material, and other short-term acts filed centrally"],
 "Article 90; Enforcement Rules Article 33."),

(AP,"第91條",1,"空污法-規費",
 "各級主管機關依本法所為之檢驗、核發許可證及受理申請審查，應如何收費？",
 ["應收取審查費、檢驗費或證書費等規費，其收費標準由中央主管機關會商有關機關定之","應一律免費辦理，所需費用由空氣污染防制基金支應，不得向申請人收取任何規費","應收取規費，其收費標準由各直轄市、縣（市）主管機關依其成本自行訂定公告","應收取規費並全數繳庫，其收費標準由行政院主計總處會商財政部核定後公告"],"a",
 "第91條：各級主管機關依本法規定所為之檢驗及核發許可證、證明或受理各項申請之審查、許可，應收取審查費、檢驗費或證書費等規費；其收費標準由中央主管機關會商有關機關定之。第43條另定中央主管機關委託辦理汽車排氣定期檢驗之費用，得由汽車排氣檢驗費扣抵。",
 "How are fees charged for inspections, permits and application reviews?",
 ["Review, inspection and certificate fees are charged, with the schedule set by the central authority with related agencies","No fees are charged at all; costs come from the air pollution control fund and applicants pay nothing whatsoever","Fees are charged, with each municipal or county authority setting and announcing its own schedule based on cost","Fees are charged and paid into the treasury, with the schedule set by the budget agency together with the Ministry of Finance"],
 "Article 91."),

(AP,"第92條",2,"空污法-受害鑑定",
 "空氣污染物受害人依本法得如何主張權利？",
 ["得向各級主管機關申請鑑定其受害原因；主管機關得會同有關機關查明原因後令排放者立即改善，受害人並得請求適當賠償","僅得向法院提起民事訴訟請求損害賠償，主管機關不受理鑑定申請，亦不得令排放空氣污染物者立即改善","得向各級主管機關申請鑑定，並由主管機關逕行核定賠償金額命排放者給付，受害人不得另行提起訴訟","得向目的事業主管機關申請補償，由該機關自空氣污染防制基金撥款賠償，排放者則不負任何賠償責任"],"a",
 "第92條：空氣污染物受害人，得向各級主管機關申請鑑定其受害原因；各級主管機關得會同有關機關查明原因後，令排放空氣污染物者立即改善，受害人並得請求適當賠償。施行細則第34條規定受害事件跨越二直轄市、縣（市）以上者，受害人得向中央主管機關申請鑑定其受害原因。",
 "What may a person harmed by air pollution do under the Act?",
 ["Apply to any competent authority to determine the cause; the authority may order immediate improvement and the victim may claim compensation","Only sue in the civil court for damages, since the authorities do not accept such applications and may not order the emitter to improve","Apply for determination, after which the authority fixes the compensation and orders payment, barring the victim from suing","Apply to the industry authority for compensation paid from the control fund, with the emitter bearing no liability at all"],
 "Article 92; Enforcement Rules Article 34."),

(AP,"第93條",3,"空污法-公民訴訟",
 "主管機關疏於執行本法時，受害人民或公益團體得如何救濟？其等待期間為何？",
 ["得以書面告知主管機關；自送達之日起六十日內仍未依法執行者，得以該機關為被告直接向行政法院提起訴訟請求判令執行","得以書面告知主管機關；自送達之日起三十日內仍未依法執行者，得以該機關為被告直接向地方法院提起民事訴訟請求賠償","得逕向監察院陳情；自陳情之日起九十日內仍未依法執行者，得以該機關為被告向行政法院提起撤銷訴訟請求救濟","得逕向行政法院聲請假處分；主管機關收受書面告知後應於七日內執行，逾期即由法院代為執行並命其負擔費用"],"a",
 "第93條：公私場所違反本法或依本法授權訂定之相關命令而各級主管機關疏於執行時，受害人民或公益團體得敘明疏於執行之具體內容，以書面告知各級主管機關；各級主管機關於書面告知送達之日起六十日內仍未依法執行者，受害人民或公益團體得以該主管機關為被告，對其怠於執行職務之行為，直接向行政法院提起訴訟，請求判令其執行；行政法院並得判命被告機關支付適當律師費用、偵測鑑定費用或其他訴訟費用。",
 "How may citizens act when the authority neglects enforcement, and after how long?",
 ["Notify the authority in writing; if it still fails to act within sixty days of service, sue it directly in the administrative court","Notify the authority in writing; if it still fails to act within thirty days of service, sue it for damages in the district court","Petition the Control Yuan; if nothing is done within ninety days, bring a revocation action against the authority in court","Seek an injunction directly; the authority must act within seven days of the notice or the court enforces at its expense"],
 "Article 93."),

(AP,"第94條",2,"空污法-檢舉獎勵",
 "人民或團體向主管機關檢舉違反本法行為者，本法有何規定？",
 ["得敘明事實或檢具證據向地方主管機關檢舉；查證屬實並處罰鍰達一定數額者得提充獎金獎勵檢舉人，並應對檢舉人身分保密","僅得向中央主管機關檢舉且應具真實姓名及地址；查證屬實者一律發給罰鍰總額二分之一之獎金，但不予保密","得匿名向任何機關檢舉；查證屬實者由目的事業主管機關發給定額獎金，主管機關對檢舉人身分不負保密義務","僅得就使用中汽車排放情形提出檢舉；對公私場所之違規行為則不得檢舉，亦無檢舉獎金及保密之規定"],"a",
 "第94條：人民或團體得敘明事實或檢具證據資料，向直轄市、縣（市）主管機關檢舉公私場所違反本法規定之行為，或使用中汽車排放空氣污染物情形；檢舉及獎勵之辦法由直轄市、縣（市）主管機關定之；被檢舉對象屬公私場所且經查證屬實並處以罰鍰者，其罰鍰金額達一定數額時，得以實收罰鍰總金額收入之一定比例提充獎金獎勵檢舉人；主管機關對檢舉人之身分應予保密。第18條第1項第13款並定明空氣污染檢舉獎金為空污費支用項目之一。",
 "What does the Act provide on public reporting of violations?",
 ["Report facts or evidence to the local authority; where fines reach a set level a share may reward the informer, whose identity is kept confidential","Report only to the central authority under a real name and address; verified reports always earn half of the fine, with no confidentiality at all","Report anonymously to any agency; industry authorities pay a fixed reward and no duty of confidentiality applies to the informer","Report only in-use vehicle emissions; violations by premises may not be reported and no reward or confidentiality rule exists"],
 "Article 94; see also Article 18(1)(13)."),

(AP,"第95條",3,"空污法-吹哨者保護",
 "公私場所對揭露違法行為之專責人員或受僱人所為之不利處分，本法有何保護規定？",
 ["公私場所不得因其揭露、作證或拒絕參與違法行為而予解僱、降調、減薪或其他不利處分，所為之不利處分無效，並由公私場所負舉證責任","公私場所得予調職但不得解僱，受僱人如認有不利處分應自行舉證證明其因果關係，主管機關不提供任何法律扶助或協助","公私場所僅不得對空氣污染防制專責人員為不利處分，其他受僱人不在保護範圍，且不利處分仍屬有效僅得請求損害賠償","公私場所所為之不利處分經主管機關核准者仍屬有效，受僱人參與違法行為而自白者不得減輕或免除其刑事責任"],"a",
 "第95條：公私場所不得因空氣污染防制專責人員或其他受僱人向主管機關或司法機關揭露違反本法之行為、擔任訴訟程序之證人或拒絕參與違反本法之行為，而予解僱、降調、減薪或其他不利之處分；所為之不利處分無效；公私場所對於該不利處分與揭露行為無關之事實負舉證責任；因揭露行為犯妨害秘密罪或背信罪者減輕或免除其刑；曾參與違法行為而揭露或自白因而查獲其他正犯或共犯者，亦減輕或免除其刑；受不利處分者，各級主管機關應提供必要之法律扶助。",
 "How does the Act protect personnel or employees who disclose violations?",
 ["Dismissal, demotion, pay cuts or other adverse measures for disclosing, testifying or refusing to join violations are void, and the premises bear the burden of proof","Transfer is allowed though dismissal is not; the employee must prove causation for any adverse measure, and the authority offers no legal assistance at all","Only dedicated air pollution control personnel are protected; other employees are not, and adverse measures remain valid with damages the sole remedy","Adverse measures approved by the competent authority remain valid, and an employee who confesses to joining a violation gets no mitigation of sentence"],
 "Article 95."),

(AP,"第96條",3,"空污法-情節重大",
 "本法所稱情節重大，包括下列何種情形？",
 ["未經合法登記或許可之污染源違反本法規定；經處分後自報停工改善經查證非屬實；一年內經二次限期改善仍繼續違反本法規定","單次排放濃度超過排放標準百分之十；未於期限內繳納空氣污染防制費；一年內經一次限期改善仍未完成改善之情形","未依規定設置專責人員；未於期限內申報季排放量；三年內經三次限期改善仍繼續違反本法規定之各種情形","公私場所資本額達新臺幣一億元以上；污染源位於一級防制區；曾遭主管機關裁處罰鍰累計達一千萬元以上"],"a",
 "第96條第1項：所稱情節重大指下列情形之一：未經合法登記或許可之污染源違反本法規定；經處分後自報停工改善經查證非屬實；一年內經二次限期改善仍繼續違反本法規定；大量排放空氣污染物嚴重影響附近地區空氣品質；排放之空氣污染物含有害空氣污染物質有危害公眾健康之虞；以未經操作許可證核定之排放管道排放或調整廢氣排放流向致未經核定之收集或處理設施排放；其他嚴重影響附近地區空氣品質之行為。施行細則第35條、第36條分別定明一年內及大量排放之認定。",
 "Which situations count as a serious case under the Act?",
 ["An unregistered or unpermitted source violating the Act; a falsely reported self-shutdown for improvement; two correction orders within a year and continued violation","A single reading exceeding the standard by ten percent; failure to pay the pollution fee on time; one correction order within a year left uncompleted","Failure to appoint any dedicated personnel; failure to report quarterly emissions on time; three correction orders within three years and continued violation","Capital of at least NT$100 million at the premises; a source located in a Class 1 district; cumulative fines already reaching NT$10 million"],
 "Article 96, paragraph 1; Enforcement Rules Articles 35 and 36."),

(AP,"第96條",3,"空污法-優惠待遇",
 "經認定情節重大之公私場所，其政府優惠待遇有何後果？優惠待遇之範圍為何？",
 ["應公開其名稱，由相關主管機關停止並追回違規行為所屬年度之優惠待遇，其後三年內不得享受政府優惠待遇；優惠包括獎勵、補助、捐助或減免之租稅、租金、費用等","應公開其名稱，由相關主管機關停止當年度優惠待遇但不予追回，其後一年內不得享受政府優惠待遇；優惠僅指中央政府所給予之各項現金補助及獎勵金","應公開其名稱並移送司法機關偵辦，其後五年內不得參與政府採購；優惠待遇之範圍限於目的事業主管機關所核定之產業升級研發補助款項","應由中央主管機關逕行廢止其操作許可證，優惠待遇不受影響仍得繼續享有；其範圍由各該優惠待遇之主管機關逐案認定並公告之"],"a",
 "第96條第2項、第3項：各級主管機關應公開依前項認定情節重大之公私場所，由提供優惠待遇之目的事業主管機關或各該法律之主管機關停止並追回其違規行為所屬年度之優惠待遇，並於其後三年內不得享受政府之優惠待遇；所稱優惠待遇包含中央或地方政府依法律或行政行為所給予該事業獎勵、補助、捐助或減免之租稅、租金、費用或其他一切優惠措施。",
 "What happens to government benefits for premises found to be in serious violation?",
 ["The name is published, benefits for that year are stopped and clawed back, and no government benefits may be enjoyed for the next three years; these cover awards, subsidies, grants and tax, rent or fee reductions","The name is published and the current year's benefits stop without clawback, with no benefits for one year afterwards; benefits mean only cash subsidies and awards granted by the central government to that enterprise","The name is published and the case is referred for prosecution, with a five-year bar from government procurement; benefits mean only industrial upgrading research subsidies approved by the relevant industry competent authority","The central authority revokes the operating permit while benefits continue unaffected; their scope is determined case by case and announced by the authority in charge of each particular benefit"],
 "Article 96, paragraphs 2 and 3."),

(AP,"第97條",3,"空污法-試車評鑑",
 "經令停止操作、停工（業）或自報停工（業）之公私場所，恢復操作前應完成何種程序？",
 ["應檢具試車計畫向地方主管機關申請試車並經核准後始得試車；並於試車期限屆滿前檢具符合排放標準之證明文件經評鑑合格後始得恢復操作","應向地方主管機關報備停工原因並繳清罰鍰後即得逕行恢復操作，無須申請試車或提出符合排放標準之證明文件供評鑑","應由環境工程技師出具改善完成證明並報中央主管機關備查後即得恢復操作，主管機關不辦理試車核准及評鑑程序","應重新申請核發設置及操作許可證，並經中央主管機關現場查驗合格後始得恢復操作，免辦理試車計畫之申請程序"],"a",
 "第97條：公私場所經直轄市、縣（市）主管機關依第59條、第61條、第62條第1項、第64條、第65條第1項、第67條第2項或第68條令停止污染源之操作、停工（業）或經令改善而自報停工（業）者，應於恢復污染源操作或復工（業）前，檢具試車計畫向直轄市、縣（市）主管機關申請試車，經核准後始得進行試車；並於試車期限屆滿前檢具符合排放標準之證明文件，報經評鑑合格後始得恢復操作或復工（業）。第98條並要求試車計畫應公開於中央主管機關指定之網站。",
 "What must premises complete before resuming operation after a shutdown order?",
 ["Submit a trial run plan to the local authority and get approval before trial running, then pass appraisal with compliance documents before resuming","Report the shutdown reason to the local authority and pay the fines, after which operation may resume without any trial run or appraisal","Have an environmental engineer certify completion and file it centrally, after which operation may resume with no trial run approval","Apply anew for installation and operating permits and pass a central on-site inspection, with no trial run plan application required"],
 "Article 97; see also Article 98."),

(AP,"第98條",2,"空污法-試車公開",
 "公私場所所提出之試車計畫，依本法應如何公開及審查？",
 ["應登載於中央主管機關指定之公開網站供民眾查詢；主管機關核准前應給予利害關係人及公益團體表示意見，以會議審查者應作成紀錄並公開","應送交目的事業主管機關備查即可，無須公開於網站；主管機關核准前得逕行決定，不必給予利害關係人或公益團體表示意見之機會","應公開於公私場所自設之網站並公告於工地現場；主管機關核准前應舉行公聽會，會議紀錄則屬內部文件不對外公開揭露","應於核准後三十日內公開於地方主管機關網站；利害關係人及公益團體僅得於核准後提出異議，主管機關並應重新審查其計畫"],"a",
 "第98條：公私場所應將依第97條第1項所提出之試車計畫，登載於中央主管機關所指定之公開網站，供民眾查詢；直轄市、縣（市）主管機關為核准前，應給予利害關係人及公益團體表示意見，作為核准之參考；以會議方式審查者，於會議後應作成會議紀錄，並公開登載於中央主管機關指定之網站。第24條第3項亦有許可證申請資料公開之類似規定。",
 "How must a trial run plan be published and reviewed?",
 ["Post it on the centrally designated public website; before approval the authority must invite views from stakeholders and NGOs, and publish meeting records","File it with the industry authority without publication; the authority may decide directly without inviting views from stakeholders or public interest groups","Post it on the firm's own website and at the site; a public hearing is held before approval but the meeting record stays internal and is never released","Post it on the local authority website within thirty days after approval; stakeholders and NGOs may object only afterwards, prompting a fresh review"],
 "Article 98; compare Article 24, paragraph 3."),

(AP,"第99條",1,"空污法-施行細則",
 "空氣污染防制法施行細則之訂定機關為何？",
 ["由中央主管機關定之，即行政院環境保護署訂定空氣污染防制法施行細則","由行政院定之，中央主管機關僅得就個別條文提出草案並報請核定發布","由中央主管機關會商經濟部後報請立法院審議通過，始得公布施行細則","由直轄市、縣（市）主管機關分別訂定，並報請中央主管機關核定備查"],"a",
 "第99條：本法施行細則，由中央主管機關定之。據此訂定之空氣污染防制法施行細則（109年9月18日修正）第1條即載明本細則依空氣污染防制法第99條規定訂定之；該細則第37條規定本細則自發布日施行。",
 "Who issues the Enforcement Rules of the Air Pollution Control Act?",
 ["The central competent authority, namely the EPA, which issued the Enforcement Rules of the Act","The Executive Yuan; the central authority may only draft articles and submit them for approval","The central authority with MOEA, subject to passage by the Legislative Yuan before promulgation","Each municipal and county authority separately, subject to approval and filing with the centre"],
 "Article 99; Enforcement Rules Article 1."),

(AP,"第100條",1,"空污法-施行日",
 "空氣污染防制法之施行日期規定為何？",
 ["本法自公布日施行，並未另定特別之施行日期或授權行政院定其施行日期","本法自公布後六個月施行，其施行日期另由行政院以命令定之並公告週知","本法自公布後一年施行，但罰則章之規定自公布後二年施行以利業者調適","本法之施行日期由中央主管機關會商有關機關報請行政院核定後公告實施"],"a",
 "第100條：本法自公布日施行。第99條則規定本法施行細則由中央主管機關定之；第14條第5項另定一百零七年六月二十五日修正之第14條第2項及第3項規定，施行至一百十四年十二月三十一日止，為個別條文之特別施行期間規定。",
 "When does the Air Pollution Control Act take effect?",
 ["It takes effect on the date of promulgation, with no separate effective date or delegation to the Executive Yuan","It takes effect six months after promulgation, with the date to be set and announced by order of the Executive Yuan","It takes effect one year after promulgation, except the penalty chapter which starts two years after promulgation","Its effective date is set by the central authority with related agencies and approved by the Executive Yuan"],
 "Article 100; compare the sunset in Article 14, paragraph 5."),
]
